    (m mx : mem) (tmp gap : list cell) (hj hk sh8 : list byte) (bflag bown : byte),
  rw_cells bsegs mx spa tmp -> Z.of_nat (cells_size tmp) = 56 -> lo <= spa ->
  rw_cells bsegs mx (spa + 56) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -160 - spa -> spa + 56 <= bv_unsigned sp + -104 ->
