Definition win_fs0 (ff : Z) (iv : Z * Z) : Prop :=
  snd iv <= ALOWSH_LO \/ AHI_LO <= fst iv \/ (fst iv = Z.shiftr ff 3 + 2147450880 /\ snd iv = Z.shiftr ff 3 + 2147450880 + 8).

Lemma win_fs0_fr : forall LF ff fp W, fresh_frame H LF 0 ff fp -> Forall (win_fs0 ff) W -> Forall (win_fr ff 8) W.
