(* [comment removed for export] *)
Definition rs_inv (ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
    (bs stb ioc implb MB tgt tn ec spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : statev) (ds junk : list byte) (E : ecv)
    (m mx : mem) : Prop :=
  exists (p : bptr) (j7 j16 j4 hj hk sha shb t0j t1j : list byte) (gap : list cell),
     rw_cells bsegs mx spa [CB 24 t0j; C8 (wz MB); C8 (wz ff); CB 16 t1j]                          (* [comment removed for export] *)
  /\ rw_cells bsegs mx (spa + 56) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -160 - spa
  /\ (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176)
  /\ rw_cells bsegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
  /\ rw_cells bsegs mx ff [CB 32 hj; C8 (wz (stb + 104)); C1 (b8 1); CB 15 hk; C8 (wz fp)]
  /\ rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 4 sha; C1 (b8 0); C1 (b8 0); CB 2 shb]    (* [comment removed for export] *)
  /\ rw_cells bsegs mx fp [C1 (b8 1)]
  /\ stk bsegs mx lo spa /\ mem_inv bsegs mx
  /\ as_RFS H ((0, ff, fp) :: LF) mx /\ fresh_frame H LF 0 ff fp /\ ACONST mx /\ stack0 mx lo shi /\ as_RFS H LF m
  /\ munch (rs_W H lo sp stb ec tgt tn ff fp) m mx /\ wmono bsegs m mx
  /\ In (p, stb, SZ_SPCI_STATE) LB /\ rblock_range stb SZ_SPCI_STATE
  /\ rw_cells bsegs mx stb (SpcHdrCells (st_hdr S) j7) /\ spc_ok (st_hdr S) /\ spc_vptr (st_hdr S) = AVP_SPCI_STATE
  /\ rw_cells bsegs mx (stb + 32) (AnyExecCells (stb + 32) ioc j16)
  /\ rw_cells bsegs mx (stb + 88) [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)]
  /\ rw_cells bsegs mx (stb + 104) (PMutexCells EBUSY) /\ (stb + 104) mod 4 = 0
  /\ AFlatBuf LB mx (stb + 144) (st_fb S) ds
  /\ APCond mx (stb + 192) 0
  /\ rw_cells bsegs mx (stb + 240) [C8 (wz 0); C4 (wz (st_code S)); CB 4 j4; C8 (wz 0); C8 (wz (st_nread S + 1)); C8 (wz (st_nread_bytes S));
                                    C8 (wz 0); C8 (wz 0); C8 (wz u64max); C8 (wz u64max)]
  /\ (st_code S = STREAM_OK \/ st_code S = STREAM_EOF) /\ 0 <= st_nread S /\ st_nread S + 1 < 2^63
  /\ 0 <= st_nread_bytes S /\ st_nread_bytes S + zlength ds < 2^63
  /\ addressable mx stb SZ_SPCI_STATE
  /\ (ds = [] -> st_code S = STREAM_EOF)
  /\ ro_cells bsegs mx bs [C8 (wz (stb + O_SPC_STORAGE))] /\ bs mod 8 = 0 /\ aplace bs 8 /\ fsobj H LF bs 8 /\ accessible mx bs 8
  /\ (bs + 8 <= lo \/ bv_unsigned sp <= bs)
  /\ ro_cells bsegs mx MB [C8 (wz tgt); C8 (wz tn)] /\ MB mod 8 = 0 /\ aplace MB 16 /\ fsobj H LF MB 16 /\ accessible mx MB 16
  /\ (MB + 16 <= lo \/ bv_unsigned sp <= MB)
  /\ rw_cells bsegs mx tgt [CB (Z.to_nat tn) junk] /\ 1 <= tn < 2^40 /\ aapp tgt tn /\ tgt + tn <= aceil /\ fsobj H LF tgt tn
  /\ accessible mx tgt tn /\ shvis mx tgt (tgt + tn)
  /\ rw_cells bsegs mx ec (ErrCodeCells E) /\ ec mod 8 = 0 /\ aapp ec 24 /\ fsobj H LF ec 24 /\ accessible mx ec 24
  /\ (ec + 24 <= lo \/ bv_unsigned sp <= ec)
  /\ AXStatics2 mx /\ AMiscVt48 mx
  /\ fsobj H LF stb SZ_SPCI_STATE
